use serde_json::{Value, from_str};

pub fn solve(input: Value) -> Value {
    let jobs: Vec<[i64; 2]> = from_str(&input.to_string()).unwrap();
    let mut finish_times: Vec<i64> = Vec::with_capacity(jobs.len());
    let mut current_time = 0;

    for job in jobs {
        let start_time = current_time.max(job[0]);
        current_time = start_time + job[1];
        finish_times.push(current_time);
    }

    Value::from(finish_times)
}
